pub fn save(&self, path: &std::path::Path) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| BivvyError::TrustError {
            message: format!("Failed to create directory {}: {}", parent.display(), e),
        })?;
    }

    let content = serde_yaml::to_string(self).map_err(|e| BivvyError::TrustError {
        message: format!("Failed to serialize trust store: {}", e),
    })?;

    // Atomic write
    let temp_path = path.with_extension("yml.tmp");
    fs::write(&temp_path, &content).map_err(|e| BivvyError::TrustError {
        message: format!("Failed to write trust store to {}: {}", temp_path.display(), e),
    })?;
    fs::rename(&temp_path, path).map_err(|e| BivvyError::TrustError {
        message: format!("Failed to rename trust store file {}: {}", path.display(), e),
    })?;

    Ok(())
}

